    @lookup_handler.implicit_lookup
    def get_current_scf_file(self, local_dir_path, file_name, timeout=60, connection=None):
        """
        Get active scf file for ASIR.

        :param str local_dir_path: path to directory to store final SCF.
        :param str file_name: file name of final SCF.
        :param float timeout: time in seconds to finish the plan operation.
        :param Union[ASIRConnection,str] connection: ASIRConnection object or if used, string name alias.
        :return str: path to the file with current SCF content.
        """
        return connection.get_active_scf_file(local_dir_path=local_dir_path, file_name=file_name, timeout=timeout)

    @lookup_handler.implicit_lookup
    def get_all_software_packages(self, connection=None):
        """
         Get all software packages installed in the BTS.

        :param Union[ASIRConnection,str] connection: ASIRConnection object or if used, string name alias.
        :return list: list of software versions eg:
                      [
                        {'activation_time': '2023-06-30T20:14:09UTC',
                         'installation_time': '2023-06-30T19:57:44UTC',
                         'service_type': 'full',
                         'sw_version': 'SBTS23R2_ENB_0000_001021_000000',
                         'usage_state': 'active'},
                         {'activation_time': '2023-06-29T18:45:41UTC',
                         'installation_time': '2023-06-29T18:28:18UTC',
                         'service_type': 'full',
                         'sw_version': 'SBTS23R1_ENB_0000_001593_000000',
                         'usage_state': 'inactive'}
                      ]
        """
        all_software_packages = connection.get_all_software_packages()
        return [record.to_dict() for record in all_software_packages]

    @lookup_handler.implicit_lookup
    def get_delta_plan_file(self, delta_plan_id, content_type, local_dir_path, file_name, timeout=60, connection=None):
        """
        Get ASIR Webem staged delta plan.

        :param str delta_plan_id: id of staged delta plan to download.
        :param str content_type: type of delta file content "auto" for short delta file or
        "full" for full SCF file containing delta.
        :param str local_dir_path: path to directory to store delta file.
        :param str file_name: name of delta file.
        :param float timeout: time in seconds to finish delta plan operation.
        :param Union[ASIRConnection,str] connection: ASIRConnection object or if used, string name alias.
        :return str: Path to ASIR delta file.
        """
        return connection.get_delta_plan_file(delta_plan_id, content_type, local_dir_path, timeout, file_name)

    @staticmethod
    def _get_uid_from_dist_name(dn, active_dist_names):
        for unit in active_dist_names:
            if unit["dn"] == dn:
                return unit["uid"]
        else:
            return None
